package android.app;
public class ProgressDialog extends AlertDialog { public static final int STYLE_SPINNER=0,STYLE_HORIZONTAL=1; private int progress,max=100; private boolean indeterminate; public ProgressDialog(android.content.Context c) { super(c); } public ProgressDialog(android.content.Context c,int theme) { super(c); } public void setProgress(int p) { progress=p; } public int getProgress() { return progress; } public void setMax(int m) { max=m; } public int getMax() { return max; } public void incrementProgressBy(int n) { progress+=n; } public void setIndeterminate(boolean b) { indeterminate=b; } public boolean isIndeterminate() { return indeterminate; } public void setProgressStyle(int style) {} public static ProgressDialog show(android.content.Context c,CharSequence title,CharSequence message) { ProgressDialog d=new ProgressDialog(c); d.setTitle(title); d.setMessage(message); d.show(); return d; } }
